+static mailbox_data_t *mbox0_alloc_slot(u8 dst, u8 ctrl, u8 *kind, u8 *index)
+{
+	mbox0_tx_slots_t *slots = &mailbox_slots[dst];
+	u8 i;
+
+	if (ctrl & MBOX0_CTRL_RESET)
+	{
+		if (slots->reset_used)
+			return NULL;
+		slots->reset_used = 1;
+		*kind = 2;
+		return &slots->reset;
