+
+	if (ctrl & MBOX0_CTRL_ACK_BOX)
+	{
+		for (i = 0; i < MBOX0_ACK_SLOT_NUM; i++)
+		{
+			if (!slots->ack_used[i])
+			{
+				slots->ack_used[i] = 1;
+				*kind = 1;
+				*index = i;
+				return &slots->ack[i];
+			}
+		}
+		return NULL;
+	}
+
+	if (ctrl & MBOX0_CTRL_SYNC_TX)
+	{
+		if (slots->sync_used)
+			return NULL;
+		slots->sync_used = 1;
+		*kind = 3;
+		return &slots->sync;
+	}
+
+	for (i = 0; i < MBOX0_CMD_SLOT_NUM; i++)
+	{
+		if (!slots->cmd_used[i])
+		{
+			slots->cmd_used[i] = 1;
+			slots->cmd_active = i + 1;
+			*kind = 0;
+			*index = i;
+			return &slots->cmd[i];
+		}
+	}
+
+	return NULL;
