+
+static void mbox0_release_slot(u8 dst, u8 kind, u8 index)
+{
+	mbox0_tx_slots_t *slots = &mailbox_slots[dst];
+
+	if (kind == 0)
+	{
+		slots->cmd_used[index] = 0;
+		if (slots->cmd_active == index + 1)
+			slots->cmd_active = 0;
+	}
+	else if (kind == 1)
+	{
+		slots->ack_used[index] = 0;
+	}
+	else if (kind == 2)
+	{
+		slots->reset_used = 0;
+	}
+	else
+	{
+		slots->sync_used = 0;
+	}
+}
 
